import sqlite3
from typing import Dict, List, Any, Tuple

# Milvus
from pymilvus import connections, Collection, utility


def get_sqlite_conn(db_path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def chunk_list(xs: List[str], n: int) -> List[List[str]]:
    return [xs[i:i+n] for i in range(0, len(xs), n)]


def safe_in_clause_params(ids: List[str]) -> Tuple[str, List[str]]:
    # returns ("?,?,?", params)
    placeholders = ",".join(["?"] * len(ids))
    return placeholders, ids


def try_load_clip_text_encoder():
    """Return a function embed_text(text)->List[float] or None if unavailable."""
    try:
        from sentence_transformers import SentenceTransformer
        model = SentenceTransformer("clip-ViT-B-32")

        def embed_text(text: str) -> List[float]:
            vec = model.encode([text], normalize_embeddings=True)
            return vec[0].tolist()

        return embed_text
    except Exception as e:
        print("[WARN] sentence-transformers/CLIP not available; skipping Milvus ranking.")
        print("       Details:", repr(e))
        return None


def main():
    # ----- Required exact configuration -----
    sqlite_paths = {
        "business": "D:/Yelp-JSON/db/sqlite3/business.db",
        "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
        "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
        "review": "D:/Yelp-JSON/db/sqlite3/review.db",
        "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
        "user": "D:/Yelp-JSON/db/sqlite3/user.db"
    }

    milvus_collections = {
        "reviews": "reviews",
        "photos": "photo_vector",
        "tips": "milvus_tip"
    }
    milvus_host = "localhost"
    milvus_port = "19530"

    # ----- Step 1: SQLite business filter -----
    biz_conn = get_sqlite_conn(sqlite_paths["business"])
    biz_cur = biz_conn.cursor()

    biz_sql = """
    SELECT business_id, name, address, city, state, postal_code, stars, review_count, categories
    FROM business
    WHERE city = ?
      AND stars >= ?
      AND review_count > ?
      AND categories LIKE ?
    ORDER BY stars DESC, review_count DESC;
    """
    biz_params = ("Metairie", 4.0, 200, "%Restaurants%")
    biz_rows = biz_cur.execute(biz_sql, biz_params).fetchall()

    if not biz_rows:
        print("No matching restaurants found in Metairie with stars>=4.0 and review_count>200.")
        return

    business_ids = [r["business_id"] for r in biz_rows]
    biz_by_id = {r["business_id"]: dict(r) for r in biz_rows}

    print(f"Matched businesses: {len(business_ids)}")

    # ----- Step 2: SQLite photo label='outside' -----
    photo_conn = get_sqlite_conn(sqlite_paths["photo"])
    photo_cur = photo_conn.cursor()

    # SQLite has a variable limit for IN parameters; chunk to be safe
    outside_photos: List[Dict[str, Any]] = []
    for chunk in chunk_list(business_ids, 500):
        placeholders, params = safe_in_clause_params(chunk)
        photo_sql = f"""
        SELECT photo_id, business_id, caption, label
        FROM photo
        WHERE label = 'outside'
          AND business_id IN ({placeholders});
        """
        rows = photo_cur.execute(photo_sql, params).fetchall()
        outside_photos.extend([dict(r) for r in rows])

    photos_by_biz: Dict[str, List[Dict[str, Any]]] = {}
    for p in outside_photos:
        photos_by_biz.setdefault(p["business_id"], []).append(p)

    # ----- Step 3: Milvus ranking by 'outdoor seating' (optional with graceful fallback) -----
    embed_text = try_load_clip_text_encoder()
    ranked_photos_by_biz: Dict[str, List[Dict[str, Any]]] = {}

    milvus_ok = False
    collection = None
    if embed_text is not None:
        try:
            connections.connect(alias="default", host=milvus_host, port=milvus_port)
            if utility.has_collection(milvus_collections["photos"]):
                collection = Collection(milvus_collections["photos"])
                collection.load()
                milvus_ok = True
            else:
                print(f"[WARN] Milvus collection not found: {milvus_collections['photos']}")
        except Exception as e:
            print("[WARN] Cannot connect/use Milvus; skipping ranking.")
            print("       Details:", repr(e))

    if milvus_ok and collection is not None:
        # Heuristics: try to detect vector field and business_id field
        field_names = [f.name for f in collection.schema.fields]
        vector_field = None
        for f in collection.schema.fields:
            # FloatVector field in pymilvus has dtype name like DataType.FLOAT_VECTOR
            if str(getattr(f, "dtype", "")).endswith("FLOAT_VECTOR") or "VECTOR" in str(getattr(f, "dtype", "")):
                vector_field = f.name
                break
        if vector_field is None:
            # common default
            vector_field = "embedding" if "embedding" in field_names else None

        has_business_id = "business_id" in field_names
        has_photo_id = "photo_id" in field_names

        if vector_field is None:
            print("[WARN] No vector field detected in Milvus schema; skipping ranking.")
            milvus_ok = False
        else:
            query_vec = embed_text("outdoor seating")

            # For each business, search within that business (if business_id field exists),
            # then intersect results with SQLite outside-photo candidates.
            for bid in business_ids:
                candidates = photos_by_biz.get(bid, [])
                if not candidates:
                    continue
                candidate_ids = set([c["photo_id"] for c in candidates])

                expr = None
                if has_business_id:
                    # restrict search to this business
                    expr = f"business_id == '{bid}'"

                try:
                    res = collection.search(
                        data=[query_vec],
                        anns_field=vector_field,
                        param={"metric_type": "IP", "params": {"nprobe": 16}},
                        limit=50,  # take more then filter down to outside candidates
                        expr=expr,
                        output_fields=[x for x in ["photo_id", "business_id"] if x in field_names]
                    )

                    hits = res[0]
                    ranked = []
                    for h in hits:
                        # Extract photo_id from entity/fields if possible
                        pid = None
                        if has_photo_id:
                            try:
                                pid = h.entity.get("photo_id")
                            except Exception:
                                pid = None
                        if pid is None:
                            # cannot map back reliably; break and fallback
                            ranked = []
                            break

                        if pid in candidate_ids:
                            ranked.append({
                                "photo_id": pid,
                                "score": float(h.score)
                            })
                        if len(ranked) >= 5:
                            break

                    if ranked:
                        # enrich with caption/label from SQLite
                        meta_by_pid = {c["photo_id"]: c for c in candidates}
                        ranked_photos_by_biz[bid] = [
                            {**meta_by_pid[r["photo_id"]], **r} for r in ranked
                        ]
                except Exception as e:
                    # If anything fails, just skip Milvus ranking for that business
                    continue

    # ----- Output -----
    # Show businesses and their outdoor photos (ranked if available else raw)
    # Keep output concise: top 10 businesses
    top_n_biz = 10
    shown = 0

    for r in biz_rows:
        bid = r["business_id"]
        photos = ranked_photos_by_biz.get(bid)
        if photos is None:
            photos = photos_by_biz.get(bid, [])[:5]

        if not photos:
            continue

        shown += 1
        print("\n---")
        print(f"{r['name']} | stars={r['stars']} | reviews={r['review_count']}")
        print(f"{r['address']}, {r['city']}, {r['state']} {r['postal_code']}")

        for p in photos:
            # p may include score if ranked
            if "score" in p:
                print(f"  photo_id={p.get('photo_id')} | label={p.get('label')} | score={p.get('score'):.4f} | caption={p.get('caption')}")
            else:
                print(f"  photo_id={p.get('photo_id')} | label={p.get('label')} | caption={p.get('caption')}")

        if shown >= top_n_biz:
            break

    if shown == 0:
        print("Businesses matched, but no outdoor/outside photos found in photo.db for them.")


if __name__ == "__main__":
    main()

