import sqlite3
import json
from datetime import datetime
from typing import Dict, List, Tuple

# ---- Fixed configuration (as required) ----
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# ---- Helpers ----
def safe_json_loads(s: str):
    if s is None:
        return {}
    s = s.strip()
    if not s:
        return {}
    try:
        return json.loads(s)
    except Exception:
        # Some ingestions store python-ish dict strings; try a minimal fallback
        # (If this fails, we just treat as empty attributes.)
        try:
            import ast
            return ast.literal_eval(s)
        except Exception:
            return {}


def truthy(v) -> bool:
    # Yelp attributes sometimes store True/False as booleans or strings
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() in {"true", "1", "yes", "y"}
    return False


def normalize_wifi(v) -> str:
    # Yelp WiFi values often: "free", "paid", "no" (strings)
    if v is None:
        return ""
    if isinstance(v, str):
        return v.strip().strip('"').lower()
    return str(v).strip().lower()


def parse_checkin_dates(date_field: str) -> List[datetime]:
    """Parse Yelp checkin.date field which is commonly a comma-separated list of timestamps."""
    if not date_field:
        return []
    parts = [p.strip() for p in date_field.split(",") if p.strip()]
    out = []
    for p in parts:
        # Common format: '2013-12-30 00:00:00'
        try:
            out.append(datetime.strptime(p, "%Y-%m-%d %H:%M:%S"))
        except Exception:
            # If format differs slightly, skip that entry
            continue
    return out


def chunked(lst, n: int):
    for i in range(0, len(lst), n):
        yield lst[i:i+n]


def main():
    city = "Wilmington"
    since = datetime(2023, 1, 1)

    # --- Step 1: candidate coffee shops in Wilmington ---
    biz_conn = sqlite3.connect(sqlite_paths["business"])
    biz_conn.row_factory = sqlite3.Row

    # Note: categories field is a comma-separated string in many Yelp ingestions
    biz_sql = """
    SELECT business_id, name, city, state, categories, attributes
    FROM business
    WHERE lower(city) = lower(?)
      AND categories IS NOT NULL
      AND lower(categories) LIKE '%coffee%'
    """

    biz_rows = biz_conn.execute(biz_sql, (city,)).fetchall()

    # --- Step 2: filter by WiFi and credit card acceptance ---
    filtered = []  # list of dicts
    for r in biz_rows:
        attrs = safe_json_loads(r["attributes"])
        wifi_val = normalize_wifi(attrs.get("WiFi"))
        cc_val = attrs.get("BusinessAcceptsCreditCards")

        has_wifi = (wifi_val != "" and wifi_val != "no")
        accepts_cc = truthy(cc_val)

        if has_wifi and accepts_cc:
            filtered.append({
                "business_id": r["business_id"],
                "name": r["name"],
                "city": r["city"],
                "state": r["state"],
                "categories": r["categories"],
                "wifi": wifi_val,
                "accepts_cc": accepts_cc
            })

    biz_conn.close()

    # If none, exit early
    if not filtered:
        print("No matching businesses found.")
        return

    # --- Step 3: fetch checkins for these business_ids ---
    chk_conn = sqlite3.connect(sqlite_paths["checkin"])
    chk_conn.row_factory = sqlite3.Row

    biz_ids = [b["business_id"] for b in filtered]

    # Build a map business_id -> date_field (or None)
    checkin_map: Dict[str, str] = {bid: "" for bid in biz_ids}

    # SQLite has a parameter limit; chunk IN queries
    for ids_chunk in chunked(biz_ids, 900):
        placeholders = ",".join(["?"] * len(ids_chunk))
        chk_sql = f"SELECT business_id, date FROM checkin WHERE business_id IN ({placeholders})"
        rows = chk_conn.execute(chk_sql, ids_chunk).fetchall()
        for row in rows:
            checkin_map[row["business_id"]] = row["date"] or ""

    chk_conn.close()

    # --- Step 4: parse and count checkins since 2023-01-01 ---
    results: List[Tuple[str, str, int]] = []  # (business_id, name, count)
    for b in filtered:
        date_field = checkin_map.get(b["business_id"], "")
        dts = parse_checkin_dates(date_field)
        cnt = sum(1 for dt in dts if dt >= since)
        results.append((b["business_id"], b["name"], cnt))

    # Sort by count desc, then name
    results.sort(key=lambda x: (-x[2], x[1] or ""))

    # Print table
    print(f"Wilmington coffee shops with WiFi and credit card acceptance: check-ins since {since.date()}\n")
    print(f"{'business_id':<24}  {'checkins_since_2023':>18}  name")
    print("-" * 80)
    for bid, name, cnt in results:
        print(f"{bid:<24}  {cnt:>18}  {name}")


if __name__ == "__main__":
    try:
        main()
    except sqlite3.Error as e:
        raise SystemExit(f"SQLite error: {e}")
    except Exception as e:
        raise SystemExit(f"Unexpected error: {e}")

