import sqlite3
import json
import ast
from datetime import datetime
from typing import Any, Dict, Optional, List, Tuple

# -----------------------------
# Fixed configuration (per prompt)
# -----------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}

# -----------------------------
# Helpers
# -----------------------------
TRUTHY = {True, 1, "1", "True", "true", "TRUE", "Yes", "yes", "Y", "y"}


def parse_attributes(raw: Any) -> Dict[str, Any]:
    """Parse Yelp 'attributes' which may be NULL, JSON string, or python-dict-like string."""
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return raw
    if not isinstance(raw, str):
        return {}

    s = raw.strip()
    if not s:
        return {}

    # Try JSON first
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        pass

    # Try Python literal dict (common when stored as text)
    # Normalize a few tokens that can break literal_eval
    s2 = s
    try:
        obj = ast.literal_eval(s2)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def has_outdoor_seating(attrs: Dict[str, Any]) -> bool:
    val = attrs.get("OutdoorSeating")
    # Sometimes nested or weird capitalization; try a fallback search
    if val is None:
        for k in ("OutdoorSeating", "Outdoor Seating", "outdoor_seating"):
            if k in attrs:
                val = attrs.get(k)
                break
    if isinstance(val, str):
        val = val.strip().strip('"').strip("'")
    return val in TRUTHY


def parse_checkin_count_since(date_str: Optional[str], cutoff: datetime) -> int:
    """checkin.date is typically: 'YYYY-MM-DD HH:MM:SS, YYYY-MM-DD HH:MM:SS, ...'"""
    if not date_str:
        return 0
    parts = [p.strip() for p in date_str.split(",") if p.strip()]
    cnt = 0
    for p in parts:
        # Most Yelp checkin strings are ISO-like.
        # datetime.fromisoformat handles 'YYYY-MM-DD HH:MM:SS'
        try:
            ts = datetime.fromisoformat(p)
        except Exception:
            # fallback: try only date part
            try:
                ts = datetime.fromisoformat(p[:10])
            except Exception:
                continue
        if ts >= cutoff:
            cnt += 1
    return cnt


def chunked(seq: List[str], size: int = 800) -> List[List[str]]:
    return [seq[i:i + size] for i in range(0, len(seq), size)]


# -----------------------------
# Main execution
# -----------------------------
cutoff = datetime.fromisoformat("2023-01-01")

conn = sqlite3.connect(sqlite_paths["business"])
conn.row_factory = sqlite3.Row
cur = conn.cursor()

try:
    # Attach checkin db so we can query both from one connection
    cur.execute("ATTACH DATABASE ? AS checkin_db;", (sqlite_paths["checkin"],))

    # Step 1: candidate coffee shops in (Saint) Louis, MO with stars >= 3.8
    business_sql = """
    SELECT business_id, name, city, state, stars, categories, attributes
    FROM business
    WHERE state = 'MO'
      AND city LIKE '%Louis%'
      AND stars >= 3.8
      AND (
        categories LIKE '%Coffee%'
        OR categories LIKE '%Café%'
        OR categories LIKE '%Cafe%'
      )
    """
    candidates = cur.execute(business_sql).fetchall()

    # Filter OutdoorSeating in Python (more robust than LIKE)
    filtered = []
    for r in candidates:
        attrs = parse_attributes(r["attributes"])
        if has_outdoor_seating(attrs):
            filtered.append({
                "business_id": r["business_id"],
                "name": r["name"],
                "city": r["city"],
                "state": r["state"],
                "stars": r["stars"],
                "categories": r["categories"],
            })

    business_ids = [x["business_id"] for x in filtered]

    # Step 2: pull checkins for these business_ids
    checkin_map: Dict[str, str] = {}
    if business_ids:
        for chunk in chunked(business_ids, size=800):
            placeholders = ",".join(["?"] * len(chunk))
            checkin_sql = f"SELECT business_id, date FROM checkin_db.checkin WHERE business_id IN ({placeholders});"
            rows = cur.execute(checkin_sql, chunk).fetchall()
            for rr in rows:
                checkin_map[rr["business_id"]] = rr["date"]

    # Step 3: compute counts since cutoff
    results = []
    for b in filtered:
        date_str = checkin_map.get(b["business_id"])  # may be None
        cnt = parse_checkin_count_since(date_str, cutoff)
        results.append({**b, "checkins_since_2023_01_01": cnt})

    # Sort by checkin count desc, then stars desc
    results.sort(key=lambda x: (x["checkins_since_2023_01_01"], x["stars"]), reverse=True)

    # Output
    print(f"Found {len(results)} St. Louis-area coffee shops (MO) with stars>=3.8 and OutdoorSeating.")
    print("Top results (sorted by check-ins since 2023-01-01):")
    for r in results[:50]:
        print(
            f"{r['name']} | {r['city']}, {r['state']} | stars={r['stars']} | "
            f"checkins_since_2023-01-01={r['checkins_since_2023_01_01']}"
        )

except Exception as e:
    raise
finally:
    try:
        cur.execute("DETACH DATABASE checkin_db;")
    except Exception:
        pass
    conn.close()
